FICHES.append(fiche(
 id='macron-president-de-gauche', affirmation="Macron, c'est la gauche au pouvoir.", volet='politique', sous_theme='Gauche et pluralisme politique',
 mots_cles=['macron est de gauche', 'macron la gauche au pouvoir', 'macron socialiste', 'macron gauchiste', 'gouvernement de gauche macron', 'macron president des riches', 'bilan macron gauche ou droite', 'macronie de gauche'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. Les principales réformes d'Emmanuel Macron vont dans le sens inverse de ce que défend la gauche : suppression de l'ISF et impôt forfaitaire sur les revenus du capital (les 1 % les plus aisés en sont les grands gagnants selon l'IPP), plafonnement des indemnités prud'homales, durcissement de l'assurance chômage, retraite à 64 ans imposée par le 49.3, loi immigration votée avec le RN. Certaines mesures ont aussi profité aux ménages modestes, et une partie de ses électeurs vient de la gauche, mais ni son bilan ni ses soutiens n'en font un pouvoir de gauche.",
 contexte="Une partie de l'extrême droite présente Emmanuel Macron comme un homme de gauche, pour renvoyer dos à dos « la gauche » et ses propres adversaires. La gauche, elle, le qualifie de « président des riches ».",
 explication="On regarde les mesures effectivement prises depuis 2017 et leurs effets mesurés par des organismes d'évaluation, puis la composition de son électorat.",
 sources=[B_MAC_IPP, B_MAC_FS, B_MAC_ORDO, B_MAC_UNEDIC, B_MAC_RETRAITES, B_MAC_IMMIG, B_MAC_CC, B_MAC_FJJ],
 faits=[
  fait("Selon l'Institut des politiques publiques, les mesures socio-fiscales de 2017-2022 ont augmenté le niveau de vie de 3,3 % pour les 1 % les plus aisés, contre 0,8 % pour les 5 % les plus modestes ; le remplacement de l'ISF par l'IFI réduit à lui seul les prélèvements d'environ 2,9 milliards d'euros par an.", 'b_mac_ipp', '2017-2022', 'France', "Les plus riches sont ceux qui ont le plus gagné, en proportion, au premier quinquennat.", 'etabli', '+3,3 %'),
  fait("Fait défavorable : selon la même étude, les gains sont « en moyenne nettement positifs » à tous les niveaux de vie, et environ 67 % des personnes sont gagnantes.", 'b_mac_ipp', '2017-2022', 'France', "Il y a eu des mesures favorables aux ménages modestes et moyens ; mais 58 % des 5 % les plus modestes sont perdants.", 'etabli', '67 %'),
  fait("Selon France Stratégie, après la réforme de 2018, les dividendes déclarés par les ménages passent d'environ 14 à 23 milliards d'euros par an, 1 % des foyers en concentrant 96 % ; aucun effet du prélèvement forfaitaire unique n'a été détecté sur l'investissement et les salaires.", 'b_mac_fs', '2013-2021', 'France', "La réforme a surtout profité aux très gros détenteurs de capital, sans effet démontré sur l'investissement promis.", 'etabli', '96 %'),
  fait("Selon Public Sénat, les ordonnances de 2017 ont plafonné les indemnités prud'homales en cas de licenciement abusif et fusionné les instances représentatives du personnel dans un comité social et économique.", 'b_mac_ordo', '2017', 'France', "Ces mesures, réclamées de longue date par le patronat, réduisent les protections des salariés.", 'etabli'),
  fait("Selon l'étude d'impact de l'Unédic, le nouveau calcul de l'allocation chômage prévu en 2019 devait toucher environ 850 000 allocataires la première année, avec une baisse moyenne de 22 % de leur allocation mensuelle nette.", 'b_mac_unedic', '2019-2021', 'France', "Les chômeurs aux emplois précaires ont vu leur indemnisation réduite.", 'estimation', '-22 %'),
  fait("Selon Public Sénat, la réforme des retraites de 2023 a relevé l'âge légal de 62 à 64 ans et a été adoptée par le 49.3, la motion de censure échouant à 9 voix, malgré douze journées de mobilisation de l'intersyndicale.", 'b_mac_retraites', '2023', 'France', "Une réforme imposée contre l'ensemble des syndicats, aux antipodes de la retraite à 60 ans défendue par la gauche.", 'etabli', '64 ans'),
  fait("Selon Politis, la loi immigration a été adoptée le 19 décembre 2023 avec les voix du RN ; Marine Le Pen y a vu « une victoire idéologique pour le Rassemblement national ».", 'b_mac_immig', '2023', 'France', "Le principal parti d'extrême droite a lui-même revendiqué le contenu de cette loi.", 'etabli'),
  fait("Selon la Fondation Jean-Jaurès, parmi les électeurs d'Emmanuel Macron au premier tour de 2022, 27 % sont « tentés par la droite », notamment le RN et LR, et 23 % « tentés par la gauche », surtout le PS.", 'b_mac_fjj', '2026', 'France', "Son électorat mêle centre gauche et droite, avec un penchant plus marqué vers la droite.", 'interpretation', '27 %'),
 ],
 court="Suppression de l'ISF, impôt forfaitaire sur le capital, plafonnement des indemnités prud'homales, baisse des allocations chômage, retraite à 64 ans par le 49.3, loi immigration saluée par Marine Le Pen : ce n'est pas un programme de gauche. Selon l'IPP, les 1 % les plus riches sont ceux qui ont le plus gagné.",
 moyen="Les grandes réformes d'Emmanuel Macron vont à l'opposé des propositions de la gauche. En 2018, il remplace l'ISF par un impôt sur l'immobilier et crée un impôt forfaitaire sur les revenus du capital : selon l'IPP, les 1 % les plus aisés gagnent 3,3 % de niveau de vie sur le quinquennat, les 5 % les plus modestes 0,8 %. Les dividendes explosent, sans effet démontré sur l'investissement selon France Stratégie.\n\nSuivent le plafonnement des indemnités prud'homales, la baisse des allocations chômage pour les emplois précaires, la retraite à 64 ans passée par le 49.3 contre tous les syndicats, et une loi immigration que Marine Le Pen a qualifiée de « victoire idéologique ». Certaines mesures ont aidé des ménages modestes et une partie de ses électeurs vient du centre gauche, mais le cœur de sa politique est libéral et, sur l'immigration, de plus en plus à droite.",
 detaille="Juger un pouvoir sur son étiquette ne suffit pas : il faut regarder ce qu'il fait. Dès 2018, l'impôt de solidarité sur la fortune est remplacé par un impôt sur la seule fortune immobilière, et les revenus du capital sont taxés à un taux forfaitaire. Selon France Stratégie, les dividendes déclarés par les ménages passent d'environ 14 à 23 milliards d'euros par an, 1 % des foyers en concentrant 96 %, et aucun effet n'est détecté sur l'investissement et les salaires des entreprises les plus exposées. L'Institut des politiques publiques montre que, sur le quinquennat 2017-2022, les 1 % les plus aisés gagnent 3,3 % de niveau de vie, contre 0,8 % pour les 5 % les plus modestes, dont une majorité est perdante.\n\nCôté travail, les ordonnances de 2017 plafonnent les indemnités prud'homales en cas de licenciement abusif et fusionnent les instances représentatives du personnel. L'assurance chômage est durcie : selon l'étude d'impact de l'Unédic, le nouveau mode de calcul devait faire baisser de 22 % en moyenne l'allocation d'environ 850 000 chômeurs. En 2023, la retraite passe de 62 à 64 ans, par le 49.3, après douze journées de mobilisation syndicale ; la motion de censure échoue à 9 voix. En décembre 2023, la loi immigration est votée avec les voix du RN ; le Conseil constitutionnel en censure ensuite 32 articles comme cavaliers législatifs, dont des restrictions à l'accès des étrangers aux prestations sociales.\n\nTout n'est pas à sens unique : selon l'IPP, les gains moyens sont positifs à tous les niveaux de vie, et une partie de l'électorat d'Emmanuel Macron vient du centre gauche. Mais selon la Fondation Jean-Jaurès, ses électeurs de 2022 sont plus nombreux à être tentés par la droite et le RN que par la gauche. Qualifier ce pouvoir de « gauche » revient à effacer ce que la gauche défend : la justice fiscale, les droits des salariés, la retraite à 60 ans et l'égalité des droits entre Français et étrangers.",
 empathie="Emmanuel Macron se présente comme ni de droite ni de gauche et une partie de ses soutiens vient du centre gauche : il est normal que certains le classent à gauche. Regarder ses décisions concrètes permet de se faire un avis par soi-même.",
 legitimes=["Une partie des électeurs d'Emmanuel Macron vient du centre gauche et reste tentée par le PS.", "Certaines mesures ont amélioré le niveau de vie de ménages modestes, et les gains moyens sont positifs selon l'IPP."],
 contre=[
  ("Il a augmenté les dépenses publiques et la dette, c'est une politique de gauche.", "La dépense en soi n'est pas un marqueur de gauche : la question est de savoir à qui elle profite. Les baisses d'impôts sur le capital ont surtout bénéficié aux 1 % les plus aisés."),
  ("Il a fait le « quoi qu'il en coûte » pendant le Covid.", "Un soutien d'urgence pendant une crise ne dit pas grand-chose de l'orientation d'un pouvoir ; ce sont les réformes durables qui comptent : fiscalité du capital, code du travail, chômage, retraites."),
 ],
 questions=["Quelle mesure d'Emmanuel Macron un électeur de gauche pourrait-il revendiquer comme la sienne ?", "Pourquoi Marine Le Pen a-t-elle parlé de « victoire idéologique » pour une loi d'un gouvernement prétendument de gauche ?"],
 limites=["L'étude de l'IPP couvre le premier quinquennat (2017-2022) ; le second n'est pas évalué ici.", "L'étude d'impact de l'Unédic est une estimation faite avant l'application de la réforme, appliquée en 2021 sous une forme modifiée.", "Le récit du vote de la loi immigration vient de Politis, hebdomadaire de gauche ; les chiffres du vote sont publics.", "La typologie de la Fondation Jean-Jaurès repose sur des probabilités de vote déclarées, pas sur un positionnement gauche-droite.", "Les fiches de Vie publique sur ces réformes n'ont pas pu être ouvertes."],
 publics={'convaincus': "Si Macron était de gauche, pourquoi Marine Le Pen aurait-elle salué sa loi immigration comme une « victoire idéologique » ? Il a supprimé l'ISF, plafonné les indemnités des salariés licenciés abusivement, baissé les allocations chômage et repoussé la retraite à 64 ans. Ce sont des mesures que la gauche combat depuis toujours.",
  'indecis': "Macron se dit ni de droite ni de gauche, d'où la confusion. Mais selon l'IPP, ses réformes fiscales ont surtout profité aux 1 % les plus riches, et ses réformes du travail, du chômage et des retraites ont été menées contre les syndicats. On peut l'appeler libéral ou centriste, pas « la gauche au pouvoir »."},
 a_actualiser='2027-06-30', raison="Fin du second quinquennat et bilans d'évaluation à paraître.",
))

# 4 ── « Les candidats RN qui tiennent des propos racistes sont des cas isolés » ──────────────
B_RAC_LCP2024 = ('b_rac_lcp2024', src("Législatives 2024 : ces candidats, qualifiés de « brebis galeuses » par Jordan Bardella, qui embarrassent le RN", 'Raphaël Marchal, LCP (La Chaîne parlementaire)', '4 juillet 2024 (mis à jour le 5 juillet 2024)',
  'https://lcp.fr/actualites/legislatives-2024-ces-candidats-qualifies-de-brebis-galeuses-par-jordan-bardella-qui',
  "Sur BFMTV le 3 juillet, Jordan Bardella évoque « Quatre ou cinq brebis galeuses » et des « erreurs de casting », le parti ayant investi près de 600 candidats en 48 heures ; les candidats dont les propos ne correspondent pas à ses vues « seront mis à la porte ». Mediapart, cité par l'article, relève « quelque 80 cas problématiques ». L'article détaille sept cas, dont des propos racistes visant les Maghrébins, la défense de propos de Jean-Marie Le Pen sur la Shoah et une photo avec une casquette de style nazi.",
  "Chaîne parlementaire.", 'secondaire'))
