FICHES.append(fiche(
 id='ecolos-interdire-barbecue', affirmation="Les écolos veulent interdire les barbecues.", volet='politique', sous_theme='Désinformation',
 mots_cles=['ecolos barbecue', 'interdire le barbecue', 'rousseau barbecue', 'barbecue virilite', 'entrecote barbecue', 'barbecue interdit', 'ecologistes contre la viande grillee', 'khmers verts barbecue'],
 verdict='trompeur', fiabilite='etabli',
 resume="Trompeur. La polémique vient d'une phrase de la députée écologiste Sandrine Rousseau, fin août 2022 à Grenoble : il faudrait changer de mentalité pour que manger une entrecôte cuite au barbecue ne soit plus un symbole de virilité. Elle parlait de mentalités et de consommation de viande, pas d'interdiction, et aucune des sources lues ne fait état d'une proposition d'interdire les barbecues. Yannick Jadot a regretté la polémique et dit avoir fait des barbecues. Les restrictions qui existent vraiment sont anciennes et sans lien avec les écologistes : arrêtés préfectoraux contre les incendies près des forêts, arrêtés municipaux et règlements de copropriété.",
 contexte="Depuis l'été 2022, « les écolos veulent interdire le barbecue » est devenu un raccourci moqueur, repris par des responsables de droite et d'extrême droite pour présenter l'écologie comme punitive.",
 explication="On revient à ce qui a été réellement dit en août 2022, d'après les dépêches de l'AFP, on vérifie s'il existe une proposition d'interdiction, et on regarde les règles qui encadrent vraiment les barbecues.",
 sources=[E_BBQ_CBS_2022, E_BBQ_AFP_2022, E_BBQ_CONNEXION_2022, E_BBQ_ARDECHE, E_BBQ_AUDE, E_BBQ_SELOGER_2023],
 faits=[
  fait("Selon l'AFP, lors d'une table ronde à Grenoble fin août 2022, Sandrine Rousseau a estimé qu'il fallait « changer de mentalité pour que manger une entrecôte cuite sur un barbecue ne soit plus un symbole de virilité ».", 'e_bbq_afp_2022', 'août 2022', 'France', "Le propos porte sur les représentations associées à la viande, pas sur une interdiction.", 'etabli'),
  fait("Le lendemain, sur LCI, elle a expliqué que réduire sa consommation de viande est l'action individuelle la plus efficace contre le changement climatique, plus encore que la voiture.", 'e_bbq_cbs_2022', 'août 2022', 'France', "Son argument est une invitation à manger moins de viande, pas à interdire un mode de cuisson.", 'etabli'),
  fait("Yannick Jadot a déclaré « Je regrette ces polémiques », dit avoir fait des barbecues l'été 2022 et n'être « pas pour l'interdiction de la viande ».", 'e_bbq_afp_2022', 'août 2022', 'France', "Le candidat écologiste à la présidentielle de 2022 récuse lui-même toute logique d'interdiction.", 'etabli'),
  fait("Aucun des articles lus sur la polémique (AFP, Connexion France) ne fait état d'une proposition d'interdire les barbecues ou la viande de la part de Sandrine Rousseau.", 'e_bbq_connexion_2022', '2022', 'France', "L'interdiction est une extrapolation de ses adversaires.", 'interpretation'),
  fait("Fait défavorable : selon l'AFP, EELV avait évoqué à la même période une interdiction des nouvelles piscines privées et des restrictions pour les jets privés.", 'e_bbq_cbs_2022', '2022', 'France', "Les écologistes proposent bien certaines interdictions ciblées, ce qui rend le procès en « écologie punitive » crédible aux yeux de certains ; mais pas pour les barbecues.", 'etabli'),
  fait("Selon l'enquête nationale INCA citée par Connexion France, la consommation médiane de viande hors volaille est de 43 grammes par jour chez les hommes, contre 27 grammes chez les femmes.", 'e_bbq_connexion_2022', '2022', 'France', "Le lien entre viande et genre évoqué par Sandrine Rousseau correspond à une réalité statistique.", 'estimation', '43 g contre 27 g'),
  fait("Les vraies restrictions viennent de la prévention des incendies : en Ardèche, un arrêté préfectoral interdit les barbecues mobiles à moins de 200 mètres des bois et landes, toute l'année pour le public et du 1er juillet au 30 septembre pour les propriétaires hors habitations et dépendances ; le préfet peut interdire tout emploi du feu en cas de risque exceptionnel.", 'e_bbq_ardeche', '2013', 'Ardèche', "Ces règles de sécurité, prises par l'État bien avant la polémique, n'ont rien à voir avec un parti écologiste.", 'etabli'),
  fait("Le maire peut limiter les barbecues à certaines heures ou les interdire en période de sécheresse, et un règlement de copropriété ou un bail peut en restreindre l'usage.", 'e_bbq_seloger_2023', '2023', 'France', "Les limites existantes relèvent de la sécurité et du voisinage.", 'etabli'),
 ],
 court="Personne n'a proposé d'interdire les barbecues. En août 2022, Sandrine Rousseau a dit qu'il fallait changer de mentalité pour que l'entrecôte au barbecue ne soit plus un symbole de virilité : une phrase sur les mentalités, pas une loi. Les vraies restrictions sont des arrêtés anti-incendie près des forêts, pris par les préfets bien avant.",
 moyen="Tout part d'une phrase prononcée par la députée écologiste Sandrine Rousseau lors d'une table ronde à Grenoble, fin août 2022 : selon l'AFP, il faudrait « changer de mentalité pour que manger une entrecôte cuite sur un barbecue ne soit plus un symbole de virilité ». Elle a ensuite expliqué que réduire sa consommation de viande était le geste individuel le plus efficace pour le climat. Aucune des sources lues ne mentionne de proposition d'interdiction, et Yannick Jadot a regretté la polémique en rappelant qu'il faisait lui aussi des barbecues.\n\nLes règles qui limitent vraiment les barbecues existent depuis longtemps et n'ont rien d'écologiste : arrêtés préfectoraux qui les interdisent près des forêts en été pour éviter les incendies, arrêtés municipaux en période de sécheresse, règlements de copropriété.",
 detaille="La formule « les écolos veulent interdire le barbecue » vient d'une polémique de la fin de l'été 2022. Lors d'une table ronde à Grenoble, la députée EELV Sandrine Rousseau a estimé, selon l'AFP, qu'il fallait « changer de mentalité pour que manger une entrecôte cuite sur un barbecue ne soit plus un symbole de virilité ». Interrogée sur LCI, elle a expliqué que réduire sa consommation de viande était l'action individuelle la plus efficace contre le changement climatique.\n\nSon propos portait donc sur les représentations : l'idée que la viande grillée serait une affaire d'hommes. Il s'appuie sur une réalité mesurée : selon l'enquête nationale INCA, les hommes consomment en médiane 43 grammes de viande hors volaille par jour, contre 27 grammes pour les femmes. On peut trouver la formule maladroite ou provocante ; elle ne contient aucune interdiction. Yannick Jadot a d'ailleurs regretté la polémique, en précisant qu'il n'était pas pour l'interdiction de la viande. Les écologistes ont, il est vrai, proposé d'autres interdictions ciblées à la même époque, comme celle des nouvelles piscines privées.\n\nLes barbecues sont bien encadrés en France, mais pour d'autres raisons. Dans les départements exposés aux feux de forêt, des arrêtés préfectoraux interdisent ou conditionnent leur usage à moins de 200 mètres des bois, surtout l'été ; le préfet peut interdire tout feu en cas de risque exceptionnel. Les maires peuvent agir en cas de sécheresse ou de nuisances, et les règlements de copropriété peuvent les restreindre. Ces règles de sécurité existaient bien avant 2022. La question de la place de la viande dans l'alimentation est traitée dans la fiche ecolos-interdire-viande.",
 empathie="Le barbecue entre amis ou en famille est un moment de plaisir et de convivialité, et personne n'aime se sentir jugé pour ce qu'il met dans son assiette. C'est justement pour cela qu'il vaut mieux savoir ce qui a vraiment été dit.",
 legitimes=["La phrase de Sandrine Rousseau a pu être vécue comme moralisatrice ou méprisante.", "Les écologistes défendent une baisse de la consommation de viande, ce qui inquiète une partie des éleveurs et des consommateurs.", "Des interdictions de barbecue existent réellement, en période de risque d'incendie."],
 contre=[
  ("Rousseau a dit que le barbecue, c'est pour les machos, donc elle veut l'interdire.", "Elle a parlé de changer les mentalités sur la viande et la virilité. Ni elle ni son parti n'ont proposé de loi d'interdiction, et Yannick Jadot a dit faire lui-même des barbecues."),
  ("Pourtant, chez moi, le barbecue est interdit l'été.", "C'est probablement un arrêté préfectoral ou municipal contre les incendies, qui existe depuis des années dans les zones proches des forêts. Il est pris par l'État pour la sécurité, pas par un parti écologiste."),
 ],
 questions=["Pouvez-vous citer une proposition de loi visant à interdire les barbecues ?", "Une interdiction de barbecue près d'une forêt en pleine canicule, est-ce de l'écologie punitive ou du bon sens contre les incendies ?"],
 limites=["Les propos de Sandrine Rousseau ont été lus à travers des dépêches de l'AFP et un article de Connexion France, pas dans un enregistrement intégral ; la formulation exacte peut légèrement varier selon les comptes rendus.", "L'absence de proposition d'interdiction repose sur les sources lues, pas sur une recherche exhaustive dans les bases parlementaires.", "Les arrêtés préfectoraux lus (Ardèche, Aude) datent de 2013 et 2014 et peuvent avoir été modifiés ; les règles varient selon les départements.", "L'impact climatique de la viande rouge n'est pas détaillé ici : voir la fiche ecolos-interdire-viande."],
 publics={'convaincus': "Cherchez la proposition de loi pour interdire le barbecue : elle n'existe pas. Sandrine Rousseau a dit qu'il fallait changer de mentalité sur la viande et la virilité, et Yannick Jadot a répondu qu'il faisait lui-même des barbecues. Les seules interdictions réelles sont les arrêtés anti-incendie des préfets, qui protègent vos forêts depuis des années.",
  'indecis': "La phrase de Sandrine Rousseau a choqué, et on peut la trouver maladroite. Mais elle parlait de mentalités, pas d'interdire quoi que ce soit, et aucune loi n'a été proposée. Si le barbecue est interdit près de chez vous l'été, c'est à cause du risque d'incendie, décidé par le préfet."},
 a_actualiser='2027-09-30', raison="Nouvelles polémiques ou propositions éventuelles sur la viande ou le barbecue.",
))


