 sources=[F_HAMAS_PUBLICSENAT_2023, F_HAMAS_PANOT_AFP_2023, F_HAMAS_SUDRADIO_2023, F_HAMAS_SURLIGNEURS_JLM, F_HAMAS_SURLIGNEURS_BOMPARD, F_HAMAS_EURLEX_2025, F_HAMAS_CONSILIUM, F_HAMAS_PUBLICSENAT_2024],
