FICHES.append(fiche(
 id='lfi-soutien-emeutiers', affirmation="LFI soutient les émeutiers.", volet='politique', sous_theme='France insoumise',
 mots_cles=['lfi soutient les emeutiers', 'lfi emeutes nahel', 'melenchon appel au calme', 'insoumis refusent appeler au calme', 'lfi casseurs', 'lfi excuse la violence', 'emeutes 2023 lfi', 'loi 2017 refus d obtemperer lfi'],
 verdict='trompeur', fiabilite='interpretation',
 resume="Trompeur. Pendant les émeutes de juin-juillet 2023 après la mort de Nahel, LFI a refusé de lancer un appel au calme, préférant exiger « la justice » ; ce choix a été dénoncé par le gouvernement et même par le communiste Fabien Roussel. Mais aucune source lue ne montre LFI appelant aux violences : Jean-Luc Mélenchon a demandé d'épargner les écoles, et LFI a proposé un fonds d'indemnisation pour les commerçants et les communes touchés. Son soutien allait à la colère contre la mort de Nahel et à une réforme de la police, comme l'abrogation de la loi de 2017 sur les tirs, que d'autres partis de gauche questionnaient aussi.",
 contexte="Nahel, 17 ans, a été tué par un policier à Nanterre le 27 juin 2023 lors d'un refus d'obtempérer. Plusieurs nuits d'émeutes ont suivi dans toute la France. L'attitude de LFI est depuis citée comme preuve de son hostilité à l'ordre républicain.",
 explication="On compare les déclarations de LFI rapportées par des sources officielles et des médias, les critiques qu'elles ont suscitées, y compris à gauche, et les propositions déposées par LFI ensuite.",
 sources=[F_EMEUTES_QAG_2023, F_EMEUTES_EUROPE1_2023, F_EMEUTES_IFOP_2023, F_EMEUTES_PUBLICSENAT_2023, F_EMEUTES_PPL_2023, F_EMEUTES_RAPPORT_2023],
 faits=[
  fait("À l'Assemblée le 4 juillet 2023, Mathilde Panot déclare : « Le retour au calme ne se décrète pas, il se construit » et propose l'abrogation de la loi Cazeneuve, une commission vérité et justice, un fonds d'indemnisation pour les commerçants et collectivités touchés et une formation plus longue des policiers.", 'f_emeutes_qag_2023', 'juillet 2023', 'France', "LFI refusait l'appel au calme comme injonction, mais proposait des réponses politiques et l'indemnisation des victimes des dégâts.", 'etabli'),
  fait("Fait défavorable : Élisabeth Borne répond à LFI : « Vous refusez de condamner clairement les violences et d'appeler au calme », et accuse le groupe d'une « excuse constante de la violence ».", 'f_emeutes_qag_2023', 'juillet 2023', 'France', "Le refus d'appeler au calme est réel et a été perçu comme une complaisance envers les violences.", 'etabli'),
  fait("Fait défavorable : le 4 juillet 2023, Fabien Roussel (PCF) se désolidarise de « Jean-Luc Mélenchon et certains insoumis » qui ont refusé d'appeler au calme : « Je me refuse à légitimer cette violence ». LFI répond n'avoir « aucune leçon à recevoir ».", 'f_emeutes_europe1_2023', 'juillet 2023', 'France', "La critique est venue aussi de la gauche, ce qui montre que l'attitude de LFI posait question au-delà de ses adversaires.", 'etabli'),
  fait("Selon une note de l'Ifop, Jean-Luc Mélenchon a demandé le 30 juin 2023 que les écoles et équipements publics soient épargnés : « L'école, il ne faut pas y toucher » ; la note ajoute qu'aucune force politique organisée n'a dirigé les émeutes et qu'un député LFI venu à Nanterre a été « violemment pris à partie ».", 'f_emeutes_ifop_2023', 'juin-juillet 2023', 'France', "LFI n'encadrait pas les émeutes et son chef a demandé de ne pas s'en prendre aux services publics.", 'etabli'),
  fait("Lors de la réunion à Matignon du 3 juillet 2023, d'autres groupes de gauche ont aussi demandé des réponses au-delà de l'ordre : André Chassaigne (PCF) : « La seule solution ne peut être la matraque » ; Cyrielle Chatelain (écologiste) regrette l'absence de « réflexion sur la loi de 2017 et l'utilisation des armes face au refus d'obtempérer ».", 'f_emeutes_publicsenat_2023', 'juillet 2023', 'France', "Remettre en cause la loi de 2017 sur les tirs policiers n'était pas propre à LFI.", 'etabli'),
  fait("Le 20 juillet 2023, LFI dépose une proposition de loi pour abroger l'article L. 435-1 du code de la sécurité intérieure, issu de la loi de 2017 ; selon le rapport de son rapporteur insoumis, le nombre de tirs mortels a été « multiplié par près de cinq » depuis cette loi. La commission des lois l'a rejetée le 22 novembre 2023.", 'f_emeutes_rapport_2023', '2017-2023', 'France', "La réponse de LFI aux émeutes est passée par la voie parlementaire ; ses chiffres viennent d'un rapport partisan, mais s'appuient sur des données de l'inspection de la police et une étude universitaire.", 'interpretation'),
 ],
 court="LFI a refusé d'appeler au calme pendant les émeutes de 2023, et même le PCF l'a critiquée. Mais aucune source ne la montre appeler à la violence : Mélenchon a demandé d'épargner les écoles, et LFI a proposé d'indemniser les commerçants et les communes touchés. Son combat portait sur la mort de Nahel et la loi de 2017 sur les tirs policiers.",
 moyen="Après la mort de Nahel, tué par un policier le 27 juin 2023, LFI a refusé de lancer un appel au calme, en répondant qu'il fallait d'abord « la justice ». Ce choix a été vivement dénoncé : la Première ministre a accusé LFI de « refuser de condamner clairement les violences », et le communiste Fabien Roussel s'est désolidarisé de Jean-Luc Mélenchon.\n\nMais refuser un appel au calme n'est pas soutenir les émeutiers. Mélenchon a demandé de ne pas toucher aux écoles ; Mathilde Panot a proposé un fonds d'indemnisation pour les commerçants et les communes touchés, et LFI a déposé une proposition de loi pour abroger l'article de la loi de 2017 sur l'usage des armes par les policiers. Le PCF et les écologistes demandaient aussi d'autres réponses que la matraque. On peut juger la posture de LFI maladroite ou irresponsable ; l'accuser de soutenir les pillages ne repose pas sur ses déclarations.",
 detaille="Le reproche s'appuie sur un fait réel. Pendant les nuits d'émeutes qui ont suivi la mort de Nahel, LFI a refusé de lancer l'appel au calme que réclamaient le gouvernement et la plupart des partis. Le 4 juillet 2023, Élisabeth Borne lui reproche de « refuser de condamner clairement les violences et d'appeler au calme ». Le même jour, Fabien Roussel, secrétaire national du PCF, se désolidarise de Jean-Luc Mélenchon et de « certains insoumis » : « Je me refuse à légitimer cette violence. »\n\nMais il faut regarder ce que LFI a dit et fait. Mathilde Panot explique que « le retour au calme ne se décrète pas, il se construit », et propose une commission vérité et justice, une formation plus longue des policiers et un fonds d'indemnisation pour les commerçants et les collectivités touchés par les destructions. Jean-Luc Mélenchon, dans une vidéo du 30 juin, demande d'épargner les écoles : « L'école, il ne faut pas y toucher. » Selon l'Ifop, aucune force politique n'a dirigé les émeutes, et un député insoumis venu dialoguer à Nanterre a été violemment pris à partie.\n\nLa vraie ligne de LFI portait sur la police. Le parti a déposé en juillet 2023 une proposition de loi pour abroger l'article de la loi de 2017 qui a assoupli les règles de tir sur les véhicules en refus d'obtempérer ; son rapport, rédigé par un député insoumis, affirme que les tirs mortels ont été multipliés par près de cinq depuis. Le texte a été rejeté en commission. Cette question n'était pas propre à LFI : les écologistes regrettaient l'absence de réflexion sur cette loi, et le PCF jugeait que « la seule solution ne peut être la matraque ».\n\nOn peut donc critiquer le refus de LFI d'appeler au calme, qui a pu être entendu comme une indulgence envers des violences qui ont d'abord frappé les quartiers populaires eux-mêmes. Mais « soutenir les émeutiers » déforme sa position : elle soutenait la colère contre la mort d'un adolescent et une réforme de la police, pas les incendies et les pillages.",
 empathie="Voir des commerces, des écoles et des mairies incendiés a été un choc, d'abord pour les habitants des quartiers concernés. Il est normal d'attendre des responsables politiques des paroles claires dans ces moments-là.",
 legitimes=["LFI a bien refusé de lancer un appel au calme, contrairement aux autres partis, y compris de gauche.", "Le communiste Fabien Roussel a lui-même reproché à certains insoumis de légitimer la violence.", "Les destructions ont d'abord touché les services publics et les commerces des quartiers populaires."],
 contre=[
  ("Ils n'ont jamais condamné les violences.", "Ils ont refusé l'appel au calme, ce qui est critiquable, mais Mélenchon a demandé d'épargner les écoles et LFI a proposé d'indemniser les commerçants et les communes touchés. Ce n'est pas un soutien aux pillages."),
  ("LFI a attisé les émeutes.", "Selon l'Ifop, aucune force politique organisée n'a dirigé les émeutes, et un député LFI venu à Nanterre a été pris à partie par les émeutiers. Les déclarations ont pu choquer ; rien n'indique qu'elles aient organisé quoi que ce soit."),
  ("Vouloir changer la loi sur les tirs, c'est être contre la police.", "Les écologistes et des chercheurs s'interrogeaient aussi sur la loi de 2017 ; encadrer l'usage des armes protège aussi les policiers de drames qui détruisent la confiance."),
 ],
 questions=["Refuser d'appeler au calme et soutenir les violences, est-ce la même chose ?", "Que faudrait-il changer pour qu'un refus d'obtempérer ne se termine plus par la mort d'un adolescent, sans mettre en danger les policiers ?"],
 limites=["Les messages publiés par Jean-Luc Mélenchon sur les réseaux sociaux pendant les émeutes n'ont pas été lus directement ; aucune formulation de ces messages n'est donc citée.", "La vidéo du 30 juin 2023 est connue à travers la note de l'Ifop.", "Les chiffres sur les tirs mortels proviennent de textes rédigés par LFI (proposition de loi et rapport d'un rapporteur insoumis), même s'ils citent l'IGPN et une étude universitaire.", "Le profil des émeutiers est traité dans la fiche voisine sur les émeutes de 2023 et les étrangers.", "Pages non ouvertes : un article d'Europe 1 (identifiant 60108) refusé par le site ; l'entretien de Mélenchon dans Jacobin était réservé aux abonnés."],
 publics={'convaincus': "Tu as raison de dire que LFI a refusé d'appeler au calme, et même les communistes le lui ont reproché. Mais soutenir les émeutiers, c'est autre chose : Mélenchon a demandé de ne pas toucher aux écoles, et LFI a proposé d'indemniser les commerçants touchés. Ce qu'elle défendait, c'est la justice pour un ado de 17 ans tué par un tir policier, et une loi sur les tirs que d'autres questionnaient aussi.",
  'indecis': "Ta question est légitime : le refus de LFI d'appeler au calme a choqué, jusque dans la gauche. Mais ses déclarations ne montrent pas d'appel à la violence : elle réclamait la justice pour Nahel, des réformes de la police et l'indemnisation des dégâts. On peut juger sa posture maladroite sans croire qu'elle soutenait les pillages."},
 a_actualiser='2027-06-30', raison="Suites judiciaires de la mort de Nahel et éventuelles réformes de l'usage des armes par la police.",
))


